import React,{useEffect,useState,useRef} from 'react';
import {timelineNodes,chapterLabel,projectStage,dateLabel} from '../../../domain/story-workspace.js';
import {usePreference,useDraft,useResource} from '../../shared/state.js';
import {useGraph,curve,CARD_WIDTH,CARD_HEIGHT,PORT_Y} from '../../shared/graph.tsx';
import {Modal} from '../../shared/preferences.tsx';
import {DocumentTextarea} from '../../shared/workspace.tsx';
import {SaveBar,ResourceState} from '../../shared/ui.jsx';
import {useWritingRequest} from '../../shared/writing-request.js';
const colors={other:'#8a94a6',family:'#b882da',partner:'#438fbf',enemy:'#d56c75',mentor:'#c99740',affiliation:'#42a592'};
export const planStatuses={idea:'讨论中',selected:'考虑采用',written:'已写入正文',dropped:'暂不采用'};
export function StoryStage({board,novelId,call,run,busy,onChapter,onMemory,onPlanning,onForeshadow,onEvent,onRelation,refresh}){
 const [mode,setMode]=usePreference(`${novelId}:timeline-view`,'narration'),[cursor,setCursor]=usePreference(`${novelId}:story-cursor`,null),[complete,setComplete]=usePreference(`${novelId}:story-complete`,false),[planning,setPlanning]=useState(false),[attach,setAttach]=useState(''),[error,setError]=useState(''),[graphOpen,setGraphOpen]=useState(false);
 const activeButton=useRef(null),cursorMounted=useRef(false);
 const rows=timelineNodes(board,mode),current=rows.find(r=>r.key===cursor?.key)||rows.find(r=>r.eventId&&r.eventId===cursor?.eventId)||rows[0],index=Math.max(0,rows.indexOf(current)),event=current?.event,stage=projectStage(board,event?.id,{complete,chapterId:current?.chapterId});
 const choose=row=>setCursor({key:row.key,eventId:row.eventId});
 const write=useWritingRequest(call);
 useEffect(()=>{if(!cursorMounted.current){cursorMounted.current=true;return;}activeButton.current?.scrollIntoView({block:'nearest',inline:'nearest'});},[current?.key,mode]);
 useEffect(()=>{if(current&&!cursor)choose(current);},[current?.key]);
 const bind=(id,remove=false)=>run(async()=>{setError('');try{await write('writing.event.update',{novelId,id:event.id,expectedRevision:event.revision,confirmed:true,value:{planningRefs:remove?event.planningRefs.filter(p=>p!==id):[...new Set([...event.planningRefs,id])]},reason:remove?'取消规划时间关联，保留原规划':'安排已有规划到时间线'});setAttach('');refresh();}catch(e){setError(e.message);throw e;}});
 const move=()=>run(async()=>{setError('');try{const p=board.planning.find(p=>p.id===attach);await write('writing.timelinePlan.move',{novelId,nodeId:p.id,expectedRevision:p.revision,eventId:event.id,eventRevisions:Object.fromEntries(board.events.filter(e=>!e.deleted&&(e.id===event.id||e.planningRefs.includes(p.id))).map(e=>[e.id,e.revision])),confirmed:true,reason:'作者移动规划时间位置'});setAttach('');refresh();}catch(e){setError(e.message);throw e;}});
 const unscheduled=board.planning.filter(p=>!board.events.some(e=>!e.deleted&&e.planningRefs.includes(p.id))&&!p.chapterRefs.length);
 const context=()=> <>
  {event&&<div className="story-node-actions"><button disabled={busy} onClick={()=>onEvent(event.id)}>编辑事件</button>{current?.chapterId&&<button onClick={()=>onChapter(current.chapterId)}>打开正文</button>}<button disabled={busy} onClick={()=>setPlanning(true)}>＋ 规划</button><button className="story-mobile-graph" onClick={()=>setGraphOpen(true)}>关系图 ↗</button></div>}
  {event?.planned&&<p className="story-plan-notice">计划情境 · 尚未确认正文</p>}{event?.review&&<p className="story-plan-notice">正文已变化，引用待复核</p>}
  <div className="story-context"><section><div className="story-section-title"><h3>规划</h3><small>{stage.planning.length}</small></div>{stage.planning.map(p=><div className={`story-plan status-${p.status}`} key={p.id}><button onClick={()=>setPlanning(p.id)}><strong>{p.title}</strong><small>{planStatuses[p.status]}</small></button>{event?.planningRefs.includes(p.id)&&<button className="story-unlink" disabled={busy} aria-label={`取消时间关联 ${p.title}`} onClick={()=>bind(p.id,true)}>移出</button>}</div>)}{!stage.planning.length&&<p className="story-empty-note">暂无规划</p>}</section>{(stage.foreshadows.length>0||!event)&&<section><div className="story-section-title"><h3>伏笔</h3><small>{stage.foreshadows.length}</small></div>{stage.foreshadows.map(f=><button className="story-foreshadow" key={f.id} onClick={()=>onForeshadow(f.id)}><strong>{f.title}</strong><small>{f.stageStatus}{f.due?' · 待回收':''}{f.review?' · 待复核':''}</small></button>)}{!stage.foreshadows.length&&<p className="story-empty-note">暂无关联伏笔</p>}{current?.chapterId&&!event&&<div className="story-node-actions"><button onClick={()=>onChapter(current.chapterId)}>打开正文</button><button disabled={busy} onClick={()=>onEvent(null,{chapterId:current.chapterId,revision:board.chapters.find(c=>c.id===current.chapterId).revision})}>＋ 本章事件</button><button className="story-mobile-graph" onClick={()=>setGraphOpen(true)}>关系图 ↗</button></div>}</section>}</div>
  {event&&<details className="story-arrange"><summary>安排已有规划</summary><div className="story-arrange-fields"><select aria-label="安排已有规划" value={attach} onChange={e=>setAttach(e.target.value)}><option value="">选择规划卡片</option>{board.planning.filter(p=>!event.planningRefs.includes(p.id)).map(p=><option key={p.id} value={p.id}>{p.title}</option>)}</select><button disabled={busy||!attach} onClick={()=>bind(attach)}>追加关联</button><button disabled={busy||!attach} onClick={move}>移到此处</button></div></details>}
 </>;
 const position=()=> <div className="story-current-title"><small>{current?.chapterId?chapterLabel(board,current.chapterId):event?.plannedChapter||'待定卷章'}{event?.storyDate||event?.storyTime?` · ${dateLabel(event.storyDate)||event.storyTime}`:''}</small><h3>{event?.title||'章节关系'}</h3></div>;
 return <section className="story-stage">
 <div className="story-axis-tools"><div className="story-mode-switch" role="group" aria-label="时间线顺序"><button aria-pressed={mode==='narration'} className={mode==='narration'?'selected':''} onClick={()=>{if(current)choose(current);setMode('narration');}}>章节顺序</button><button aria-pressed={mode==='story'} className={mode==='story'?'selected':''} onClick={()=>{if(current)choose(current);setMode('story');}}>故事时间</button></div><div className="story-step-controls"><button aria-label="上一个时间节点" disabled={!index} onClick={()=>choose(rows[index-1])}>‹</button><small>{rows.length?index+1:0} / {rows.length}</small><button aria-label="下一个时间节点" disabled={!rows.length||index===rows.length-1} onClick={()=>choose(rows[index+1])}>›</button></div></div>
 <div className="story-workspace"><div className="story-timeline-column"><div className="story-axis" aria-label="当前时间线" data-axis={mode}>{rows.map((row,i)=>{
  const selected=current?.key===row.key,refs=row.event?.memoryRefs||[],plans=board.planning.filter(p=>row.event?.planningRefs.includes(p.id)||p.chapterRefs.some(r=>r.chapterId===row.chapterId)),shadows=board.foreshadows.filter(f=>row.event?.foreshadowRefs.includes(f.id)||f.evidence.some(r=>r.chapterId===row.chapterId)||(row.chapterId&&f.targetChapterId===row.chapterId)),date=dateLabel(row.event?.storyDate)||row.event?.storyTime;
  return <article key={row.key} className={`story-timeline-node ${selected?'is-current':''}`}><span className="story-time-dot" aria-hidden="true"/><button ref={selected?activeButton:null} className="story-node-select" aria-current={selected?'step':undefined} onClick={()=>choose(row)}><small className="story-node-position">{mode==='story'?(date||'时间待定'):(row.chapterId?chapterLabel(board,row.chapterId):row.event?.plannedChapter||'待定卷章')}</small><strong>{row.event?.title||'尚无事件'}{row.event?.planned&&<em>计划</em>}</strong>{mode==='narration'&&date&&<span className="story-node-date">{date}</span>}{mode==='story'&&<span className="story-node-date">{row.chapterId?chapterLabel(board,row.chapterId):row.event?.plannedChapter||'待定卷章'}</span>}<span className="story-node-tags">{refs.slice(0,3).map(id=><span key={id}>{board.nodes.find(n=>n.id===id)?.name||'资料'}</span>)}{plans.length>0&&<span className="plan-count">{plans.length} 规划</span>}{shadows.length>0&&<span className="shadow-count">{shadows.length} 伏笔</span>}</span></button>{selected&&<div className="story-mobile-context">{context()}</div>}</article>;
 })}</div>{!rows.length&&<div className="chart-empty">先添加一个故事事件，或安排待写卷章。</div>}
 <button className="story-add-next" disabled={busy} onClick={()=>onEvent(null,{planned:true,order:event?event.order+1:10,plannedChapter:event?.plannedChapter})}>＋ {event?'后续事件':'计划节点'}</button>
 <details className="story-waiting"><summary>待安排规划 <small>{unscheduled.length}</small></summary>{unscheduled.map(p=><div className={`story-plan status-${p.status}`} key={p.id}><button onClick={()=>onPlanning(p.id)}><strong>{p.title}</strong><small>{planStatuses[p.status]}</small></button>{event&&<button disabled={busy} onClick={()=>bind(p.id)}>安排</button>}</div>)}</details></div>
 <aside className="story-inspector" aria-label="当前节点关系与规划">{position()}<div className="story-graph-toolbar"><span>人物与世界</span><label><input type="checkbox" checked={complete} onChange={e=>setComplete(e.target.checked)}/> 完整资料</label></div><StageGraph key={novelId} {...{stage,board,novelId,onMemory}} onRelation={onRelation}/><div className="story-inspector-content">{context()}</div></aside></div>
 {error&&<p role="alert">{error}</p>}
 {graphOpen&&<Modal title="当前节点关系图" className="story-graph-modal" close={()=>setGraphOpen(false)}>{position()}<div className="story-graph-toolbar"><div className="story-step-controls"><button aria-label="上一个时间节点" disabled={!index} onClick={()=>choose(rows[index-1])}>‹</button><small>{index+1} / {rows.length}</small><button aria-label="下一个时间节点" disabled={index===rows.length-1} onClick={()=>choose(rows[index+1])}>›</button></div><label><input type="checkbox" checked={complete} onChange={e=>setComplete(e.target.checked)}/> 完整资料</label></div><StageGraph fitOnOpen {...{stage,board,novelId,onMemory}} onRelation={(edge,at)=>{setGraphOpen(false);onRelation(edge,at);}}/></Modal>}
 {planning&&(event||planning!==true)&&<PlanEditorLoader key={planning===true?event.id:planning} id={planning===true?null:planning} {...{call,novelId,run,busy,event,onPlanning}} close={()=>setPlanning(false)} saved={()=>{setPlanning(false);refresh();}}/>}</section>;

}
function PlanEditorLoader(props){const resource=useResource(()=>props.id?props.call('planning.get',{novelId:props.novelId,nodeId:props.id}):Promise.resolve(null),[props.call,props.novelId,props.id]);return props.id?<ResourceState resource={resource}>{resource.value&&<TimelinePlanEditor {...props} initial={resource.value.node}/>}</ResourceState>:<TimelinePlanEditor {...props}/>;}
function TimelinePlanEditor({call,novelId,run,busy,event,close,saved,initial,onPlanning}){
 const write=useWritingRequest(call),{value:v,base,change,accept,dirty,cacheError}=useDraft(`${novelId}:timeline-plan:${initial?.id||event.id}`,initial||{title:'',summary:'',content:'',status:'idea'}),[error,setError]=useState('');
 return <Modal title={initial?'在时间线上编辑规划':'在时间线上新建规划'} close={close} className="chapter-materials-modal"><p>{event?`安排在「${event.title}」`:'关联正文章节'}；与网格中的同一张规划卡片同步。</p>{initial&&<button onClick={()=>onPlanning(initial.id)}>在原网格中查看 / 历史</button>}<div className="structure-form"><label>标题<input aria-label="时间线规划标题" value={v.title} onChange={e=>change({...v,title:e.target.value})}/></label><label>摘要<input value={v.summary} onChange={e=>change({...v,summary:e.target.value})}/></label><label>状态<select value={v.status} onChange={e=>change({...v,status:e.target.value})}>{['idea','selected',...(initial?.chapterRefs?.length?['written']:[]),'dropped'].map(s=><option key={s} value={s}>{planStatuses[s]}</option>)}</select></label><label>规划内容<DocumentTextarea aria-label="时间线规划内容" value={v.content} onChange={e=>change({...v,content:e.target.value})}/></label></div><SaveBar dirty={dirty} busy={busy} error={error||cacheError} invalid={!v.title.trim()?'填写标题':null} label="保存规划" onSave={()=>run(async()=>{try{if(initial){await write('planning.apply',{novelId,reason:'作者在时间线上编辑共享规划',operations:[{op:'node.update',id:initial.id,expectedRevision:base.revision,value:v}]});accept((await call('planning.get',{novelId,nodeId:initial.id})).node);}else{await write('writing.timelinePlan.create',{novelId,eventId:event.id,expectedEventRevision:event.revision,confirmed:true,value:v,reason:'作者在时间线上创建规划'});change({title:'',summary:'',content:'',status:'idea'});}saved();}catch(e){setError(e.message);throw e;}})}/></Modal>;
}
function StageGraph({stage,board,novelId,onMemory,onRelation,fitOnOpen=false}){
 const all=board.nodes,fallback=Object.fromEntries(all.map((n,i)=>[n.id,{x:40+i%3*332,y:64+Math.floor(i/3)*230}]));
 const graph=useGraph({nodes:all,edges:stage.edges,fallback,scopeKey:`${novelId}:story-stage`,busy:false,visibleIds:stage.nodes.map(n=>n.id),onLayout:async()=>false,onConnect:async()=>false});
 useEffect(()=>{if(!fitOnOpen)return;const frame=requestAnimationFrame(()=>{if(graph.scroll.current?.clientWidth)graph.fit();});return()=>cancelAnimationFrame(frame);},[fitOnOpen]);
 const visible=new Set(stage.nodes.map(n=>n.id)),points=graph.points,positions=stage.nodes.map(n=>points[n.id]),left=Math.min(-200,...positions.map(p=>p.x-200)),top=Math.min(-200,...positions.map(p=>p.y-200)),width=Math.max(800,...positions.map(p=>p.x+CARD_WIDTH+200))-left,height=Math.max(600,...positions.map(p=>p.y+CARD_HEIGHT+200))-top;
 return <div className="story-graph planning-canvas-scroll" ref={graph.scroll} style={graph.viewportStyle} {...graph.scrollProps}><div className="planning-canvas relation-canvas" ref={graph.surface} style={graph.worldStyle}><svg className="planning-lines" width={width} height={height} viewBox={`${left} ${top} ${width} ${height}`} style={{left,top,width,height}} aria-label="随时间变化的关系图">{stage.edges.filter(e=>visible.has(e.from)&&visible.has(e.to)).map(e=>{const a=points[e.from],b=points[e.to],path=curve({x:a.x+CARD_WIDTH,y:a.y+PORT_Y},{x:b.x,y:b.y+PORT_Y}),x=(a.x+CARD_WIDTH+b.x)/2,y=(a.y+b.y)/2+PORT_Y;return <g key={e.id} opacity={e.future?.25:1}><path d={path} fill="none" stroke={colors[e.category]} strokeWidth="3" strokeDasharray={e.style==='dotted'?'2 6':e.style==='dashed'?'8 6':undefined}/><path className="edge-hit" d={path} role="button" tabIndex={0} aria-label={`编辑阶段关系 ${e.name||'未命名'}`} onClick={()=>onRelation(e,stage.event)} onKeyDown={k=>{if(k.key==='Enter')onRelation(e,stage.event);}}/><g role="button" aria-label={`关系 ${e.name||'未命名'}`} style={{pointerEvents:'all',cursor:'pointer'}} onPointerDown={k=>k.stopPropagation()} tabIndex={0} onClick={()=>onRelation(e,stage.event)} onKeyDown={k=>{if(k.key==='Enter')onRelation(e,stage.event);}}><rect x={x-72} y={y-18} width="144" height="36" rx="8" fill="var(--cg-paper)" stroke={colors[e.category]}/><text x={x} y={y+5} textAnchor="middle" fill="var(--cg-ink)" fontSize="14">{(e.name||'未命名关系').slice(0,10)}</text></g></g>;})}</svg>{stage.nodes.map(n=><section key={n.id} data-node-id={n.id} {...{...graph.cardProps(n.id,()=>onMemory(n.id)),onPointerDown:undefined,onClick:()=>onMemory(n.id)}} className={`planning-card setting-card kind-${n.type==='character_card'?'character':'world'}`} style={{left:points[n.id].x,top:points[n.id].y,opacity:n.future?.3:1}}><small>{n.type==='character_card'?'角色':'世界'}{n.future?' · 尚未进入':n.entryUnset?' · 进入位置未指定':''}</small><button className="planning-title">{n.name}</button><p>{n.ageLabel||n.category||n.summary||'点击打开完整资料'}</p></section>)}</div><div className="graph-view-controls"><button onClick={()=>graph.fit()}>适应</button><button aria-label="缩小阶段图" onClick={()=>graph.zoomTo(graph.zoom/1.2)}>−</button><button onClick={()=>graph.zoomTo(1)}>{Math.round(graph.zoom*100)}%</button><button aria-label="放大阶段图" onClick={()=>graph.zoomTo(graph.zoom*1.2)}>＋</button></div></div>;
}
